diff --git a/src/api/worker/EventBusClient.ts b/src/api/worker/EventBusClient.ts
--- a/src/api/worker/EventBusClient.ts
+++ b/src/api/worker/EventBusClient.ts
@@ -1,22 +1,28 @@
 import {EntityUpdate} from "../common/EntityUpdate"
 import {UnreadCountUpdate} from "../common/UnreadCountUpdate"
+import {TaskQueue} from "../../utils/TaskQueue"

 export class EventBusClient {
-    private _onMessage: (message: any) => void
+    private _entityUpdateQueue = new TaskQueue()
+    private _onMessage: (message: any) => Promise<void>

-    constructor(onMessage: (message: any) => void) {
+    constructor(onMessage: (message: any) => Promise<void>) {
         this._onMessage = onMessage
     }

     public onEvent(event: any): void {
         const data = JSON.parse(event.data)
         if (data.type === "entityUpdate") {
-            this._handleEntityUpdate(data.payload)
+            this._entityUpdateQueue.run(async () => {
+                await this._handleEntityUpdate(data.payload)
+            })
         } else if (data.type === "unreadCountUpdate") {
-            this._handleUnreadCountUpdate(data.payload)
+            this._entityUpdateQueue.run(async () => {
+                await this._handleUnreadCountUpdate(data.payload)
+            })
         }
     }

-    private _handleEntityUpdate(update: EntityUpdate): void {
-        this._onMessage({type: "entityUpdate", update})
+    private async _handleEntityUpdate(update: EntityUpdate): Promise<void> {
+        await this._onMessage({type: "entityUpdate", update})
     }

-    private _handleUnreadCountUpdate(update: UnreadCountUpdate): void {
-        this._onMessage({type: "unreadCountUpdate", update})
+    private async _handleUnreadCountUpdate(update: UnreadCountUpdate): Promise<void> {
+        await this._onMessage({type: "unreadCountUpdate", update})
     }
 }
